  System.Windows.Media.Geometry LcdArc(double value,bool right){double ratio=Math.Max(0,Math.Min(1,(value-(right?DS.MinTemp2:DS.MinTemp))/Math.Max(1,(right?DS.MaxTemp2:DS.MaxTemp)-(right?DS.MinTemp2:DS.MinTemp))));if(ratio<=0)return Geometry.Empty;double a=90,b=90+(right?-1:1)*ratio*170;Func<double,Point> pt=deg=>new Point(95+76*Math.Cos(deg*Math.PI/180),95+76*Math.Sin(deg*Math.PI/180));var f=new PathFigure{StartPoint=pt(a)};f.Segments.Add(new ArcSegment(pt(b),new Size(76,76),0,false,right?SweepDirection.Counterclockwise:SweepDirection.Clockwise,true));return new PathGeometry(new[]{f});}
